  const young = [...s.world.entities.values()].filter((e) => e.kind.startsWith("styl_tree") && !e.harvested && ["sapling", "young"].includes(growthStage(e)));
  assert.ok(young.length > 0);
  for (const e of young) assert.ok(!lot.trees.includes(e));
  run(s, 600);
